@cute.kernel
def pipelined_gemm_kernel(gA: cute.Tensor, gB: cute.Tensor, gC: cute.Tensor, smem_A: cute.Tensor, smem_B: cute.Tensor, tiled_mma: cute.TiledMma):
    for k_tile in cutlass.range(num_k_tiles, prefetch_stages=3):
        stage_idx = k_tile % total_stages
        cute.copy(tma_A, gA[:, :, k_tile], smem_A[:, :, stage_idx])
        cute.copy(tma_B, gB[:, :, k_tile], smem_B[:, :, stage_idx])
        cute.arch.syncthreads()
        cute.gemm(tiled_mma, acc, smem_A[:, :, stage_idx], smem_B[:, :, stage_idx], acc)
    cute.copy(acc, gC)

